#!/usr/bin/env python3
"""Read-only publication integrity and optional bounded audit replay; no network."""
PINS = {'packs': [{'archive': {'bytes': 9846, 'path': 'DISTINCT_PROGRESSION_DIFFS_2487_AUTHOR_SAFE_FREEZE.zip', 'sha256': '8131ce688a36e732a7fc6a97e59179c4b2d6a4c5131e49ce305566f811439f64'}, 'folder': 'author_original', 'manifest': {'bytes': 1517, 'path': 'DISTINCT_PROGRESSION_DIFFS_2487_AUTHOR_EXTERNAL_MANIFEST.json', 'sha256': '04af8441ecfc9b46c1ffde3cb679d42ce4968aac5ae9df5cf60fe2c155d8b710'}, 'members': [{'bytes': 1252, 'path': 'APPROACH_LOG.md', 'sha256': '1447c7dc816b0cb7a885876a9387144be87f5351a1da72e4cf35d15105aa92d9'}, {'bytes': 4981, 'path': 'PROOF.md', 'sha256': 'c7725783fabe1fc4426054515d52034c528308a7e579437029025bedebf3e952'}, {'bytes': 3524, 'path': 'REFERENCES.md', 'sha256': '33ea30151041b9a22232d691503d8c3e02e3e0817b422ff9a191a0191f78e9e0'}, {'bytes': 5395, 'path': 'REPORT.md', 'sha256': '6271aaa139e6ef0b862a4f4a60e1273e10c6f47b7110304bf52341590c1cb776'}, {'bytes': 675, 'path': 'STATUS.json', 'sha256': 'fffaadd240f60f77d7a13707b57f7f77a1cd499f397a34d8c3e4b810e6db3ff7'}, {'bytes': 4395, 'path': 'VERIFICATION_METADATA.json', 'sha256': 'eab11d87bda2074342c8ea25d3202a709df29d2f25698aefec93099bcfecb8b3'}], 'tag': 'AUTHOR'}, {'archive': {'bytes': 15342, 'path': 'DISTINCT_PROGRESSION_DIFFS_2487_INDEPENDENT_AUDIT_SAFE.zip', 'sha256': '9e0cc137bf1e42351f37418dae68d18ff608a78641fa0bd33c0834acf4c56d02'}, 'folder': 'independent_audit', 'manifest': {'bytes': 2322, 'path': 'DISTINCT_PROGRESSION_DIFFS_2487_INDEPENDENT_AUDIT_EXTERNAL_MANIFEST.json', 'sha256': '62e388fb234e13a825fd15056c3728918f36aa1258ac717c80470c5039b24e2a'}, 'members': [{'bytes': 2043, 'path': 'ACCEPTANCE.json', 'sha256': 'd0e9979740baee7b6b0dc0c361ecdf8c6b3f0ba330fae83fe8a2724acff116e1'}, {'bytes': 12845, 'path': 'AUDIT.md', 'sha256': 'c79a9ecee515f2ce2e579744a2f707e1b549db4cdd8b29795e046789549999e8'}, {'bytes': 1368, 'path': 'MANIFEST.json', 'sha256': '72d1d3595a643c51593136afdf7b8a2b28cc8ebf453f01a92ef2ab9919913a4e'}, {'bytes': 778, 'path': 'REPLAY_VALIDATION.json', 'sha256': '03a6071a1c2f0060164aa5a481d5b875069f2ccd0a253fba2ee6a17458c395f9'}, {'bytes': 4531, 'path': 'SOURCE_VERIFICATION.json', 'sha256': '02948c19b00b681f82689d69ddde2ec1cb85063f1419a27fc4199a05941968d2'}, {'bytes': 4155, 'path': 'VERIFICATION_RESULTS.json', 'sha256': 'cd40aed43ad21db9a9511352530e2f53f1c1d9d8eebd873936f977d5ca8035b7'}, {'bytes': 8321, 'path': 'verify_audit.py', 'sha256': 'c0ca8d1e5429fbfc88b58f769db982794baa0df2dc6711a8d44bb84466cbab1f'}], 'tag': 'INDEPENDENT_AUDIT'}], 'queue_base': {'bytes': 392513, 'sha256': 'be0b59c8866f1a7e55cb6be1924fff339c1fb9ce7a58122b55c9a077da6b7e52'}, 'queue_new': {'bytes': 392816, 'sha256': '315aba192898812c31fc049a6977669a7a64bcaf1fa7a92fd5f76fb770a0a842'}}
import argparse,hashlib,io,json,stat,subprocess,sys,zipfile
from pathlib import Path,PurePosixPath
H=lambda b:hashlib.sha256(b).hexdigest()
def need(v,s):
 if not v:raise ValueError(s)
def pin(b,p,s):need((len(b),H(b))==(p['bytes'],p['sha256']),s+' pin mismatch')
def safe(n):
 p=PurePosixPath(n);need(n and not p.is_absolute() and all(s not in ('','.','..') for s in n.split('/')) and '\\' not in n and ':' not in n,'unsafe path');return p

def inspect(root):
 need(root.is_dir() and not root.is_symlink(),'root');packs={}
 for p in PINS['packs']:
  ab=(root/'archives'/p['archive']['path']).read_bytes();mb=(root/'archives'/p['manifest']['path']).read_bytes();pin(ab,p['archive'],'archive');pin(mb,p['manifest'],'external manifest');m=json.loads(mb);need(m['problem_id']==2487 and m['problem_number']=='EP-1097' and m['members']==p['members'],'manifest identity')
  need(m['archive']['bytes']==p['archive']['bytes'] and m['archive']['sha256']==p['archive']['sha256'],'archive binding');names=[e['path'] for e in p['members']];need(len(names)==len(set(names)),'unique pins');out={}
  with zipfile.ZipFile(io.BytesIO(ab)) as z:
   need(z.namelist()==names and z.testzip() is None,'ZIP inventory and CRC')
   for e in p['members']:
    n=e['path'];safe(n);i=z.getinfo(n);mode=i.external_attr>>16;need(stat.S_ISREG(mode) and not mode&0o111 and not i.flag_bits&1,'member mode');b=z.read(n);pin(b,e,'member');b.decode('utf-8');f=root/p['folder']/n;need(f.is_file() and not f.is_symlink() and f.read_bytes()==b,'loose member equality');out[n]=b
    if n.endswith('.json'):json.loads(b)
  actual={f.relative_to(root/p['folder']).as_posix() for f in (root/p['folder']).rglob('*') if f.is_file()};need(actual==set(names),'loose inventory');packs[p['tag']]=out
 orig=packs['AUTHOR'];audit=packs['INDEPENDENT_AUDIT'];acc=json.loads(audit['ACCEPTANCE.json']);am=json.loads(audit['MANIFEST.json']);need(am['members']==[e for e in PINS['packs'][1]['members'] if e['path']!='MANIFEST.json'],'internal audit manifest')
 for key,p in [('author_archive',PINS['packs'][0]['archive']),('author_external_manifest',PINS['packs'][0]['manifest'])]:need(acc[key]==dict(name=p['path'],bytes=p['bytes'],sha256=p['sha256']),'exact acceptance archive binding')
 need(acc['decision']=='accept_exact_author_archive_unchanged' and acc['classification']=='verified_prior_partial_resolution' and acc['main_problem_status']=='open_in_inspected_sources' and acc['three_halves_subquestion_status']=='disproved_by_prior_work','acceptance decision');need(acc['problem_id']==2487 and acc['problem_number']=='EP-1097' and acc['rank']==904 and acc['new_substantive_approaches']==0 and acc['turn_limit']==5,'accepted identity/counts')
 need(not any(acc[k] for k in ('original_author_files_changed','mathematical_correction_required','new_solution_claim','novelty_claim','full_optimal_exponent_resolved','endpoint_big_O_at_infimum_claimed','optimizer_certification_performed','full_current_literature_census_claimed','fresh_successful_live_tracker_inspection_claimed','bounded_replay_is_formal_proof_verification')),'accepted scope');origstatus=json.loads(orig['STATUS.json']);need(origstatus['independent_audit_status']=='pending' and not origstatus['publication_performed'],'historical status preserved')
 pub=json.loads((root/'PUBLICATION_METADATA.json').read_bytes());need(pub['problem_id']==2487 and pub['rank']==904 and pub['queue_status']=='unsolved' and pub['turns']=='0/5' and pub['new_substantive_approaches']==0 and pub['turn_limit']==5,'publication classification');need(not any(pub[k] for k in ('full_optimal_exponent_resolved','novelty_claim','optimizer_certification_performed','endpoint_growth_claim','correction_required','fresh_source_retrieval')),'publication limits')
 mf=json.loads((root/'PUBLICATION_MANIFEST.json').read_bytes());need(mf['problem_id']==2487,'manifest target');names=[e['path'] for e in mf['files']];need(len(names)==len(set(names)),'unique publication inventory');actual={f.relative_to(root).as_posix() for f in root.rglob('*') if f.is_file()};need(actual==set(names)|{'PUBLICATION_MANIFEST.json'},'exact publication inventory')
 for f in root.rglob('*'):need(not f.is_symlink(),'symlink excluded')
 for e in mf['files']:safe(e['path']);pin((root/e['path']).read_bytes(),e,'publication '+e['path'])
 return dict(status='PASS',archives=2,archive_members=13,loose_members=13,exact_acceptance_binding=True,originals_unchanged=True,inventory_exact=True,formal_proof_verification=False,optimizer_certification=False)

def verify(root,a):
 root=Path(root);out=inspect(root);out['optimization_level']=sys.flags.optimize;out['external_input_replay']=dict(performed=False);out['queue_checks']=dict(performed=False)
 external=[a.catalog,a.problems,a.reports,a.pdf_directory]
 if any(external):
  need(all(external),'all three complete corpus files and PDF directory required');p=PINS['packs'][0];cmd=[sys.executable,'-I','-S','-B']+(['-O'] if sys.flags.optimize else [])+[str(root/'independent_audit/verify_audit.py'),'--author-archive',str(root/'archives'/p['archive']['path']),'--author-manifest',str(root/'archives'/p['manifest']['path'])]
  for key,val in zip(('catalog','problems','reports','pdf-directory'),external):cmd+=['--'+key,str(Path(val).resolve())]
  r=subprocess.run(cmd,capture_output=True,check=False);need(r.returncode==0,'frozen audit replay failed');need(r.stdout==(root/'independent_audit/VERIFICATION_RESULTS.json').read_bytes(),'frozen replay result mismatch');v=json.loads(r.stdout);need(v['all_checks_passed'],'frozen replay acceptance');out['external_input_replay']=dict(performed=True,complete_corpus_files=3,source_pdf_files=4,statement_and_full_pair_match=True,exact_report_key_absent=True,empty_report_fallback_verified=True,forward_subsets=128,reverse_graphs=512,seed_depths=list(range(1,7)),stdout_sha256=H(r.stdout),source_retrieval=False,source_theorem_inspection_repeated=False)
 if a.queue_base or a.queue_current:
  need(a.queue_base and a.queue_current,'both queue inputs required');b=Path(a.queue_base).read_bytes();n=Path(a.queue_current).read_bytes();pin(b,PINS['queue_base'],'base queue');pin(n,PINS['queue_new'],'new queue');bl=b.splitlines(keepends=True);nl=n.splitlines(keepends=True);need(len(bl)==len(nl),'queue length');ii=[i for i,(x,y) in enumerate(zip(bl,nl)) if x!=y];need(len(ii)==1,'one queue row');i=ii[0];need(bl[i].startswith(b'| 904 | 2487 / EP-1097 |'),'queue target');bc=bl[i].split(b'|');nc=nl[i].split(b'|');need(len(bc)==len(nc) and [j for j,(x,y) in enumerate(zip(bc,nc)) if x!=y]==[8,11],'Status and Findings only');need(nc[8]==b' unsolved ' and nc[9]==b' 0/5 ','canonical row');out['queue_checks']=dict(performed=True,changed_rows=1,changed_cells=['Status','Findings'],turns_preserved='0/5',all_unrelated_bytes_preserved=True)
 return out
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,default=Path(__file__).resolve().parent)
 for n in ('catalog','problems','reports','pdf-directory','queue-base','queue-current'):p.add_argument('--'+n)
 a=p.parse_args();print(json.dumps(verify(a.root,a),indent=2,sort_keys=True))
